                <div className="flex items-center mb-4 md:mb-0">
                  <div className="h-16 w-16 rounded-full overflow-hidden border-2 border-white mr-4">
                    <img 
                      src={playerData.image || `/images/players/${detailPlayer.position}.${detailPlayer.position <= 3 ? (detailPlayer.position === 1 ? 'jpeg' : detailPlayer.position === 2 ? 'jpg' : 'avif') : 'webp'}`} 
