              <h3 className="text-xl font-bold text-champions-blue mb-6">Trayectoria en Equipos</h3>

              {playerData.equipos && playerData.equipos.length > 0 ? (
                <div className="space-y-8">
                  {playerData.equipos.map((team, idx) => (
                    <div key={idx} className="bg-gray-50 rounded-lg shadow p-6 border border-gray-200">
                      {/* Cabecera del equipo */}
                      <div className="flex flex-col md:flex-row items-center justify-between mb-6 pb-4 border-b border-gray-200">
                        <div className="flex items-center mb-4 md:mb-0">
                          <div className="bg-champions-blue text-white h-12 w-12 rounded-full flex items-center justify-center font-bold text-lg mr-4">
                            {team.equipo.substring(0, 2).toUpperCase()}
