      name: detailPlayer.name,
      temporadas: [
        { 
          temporada: '2008-2009', 
          equipo: 'Barcelona', 
          goles: 9, 
          partidos: 12, 
          promedio: 0.75,
          resultado: 'Campeón',
          destacado: true
        },
        { 
          temporada: '2010-2011', 
          equipo: 'Barcelona', 
          goles: 12, 
          partidos: 13, 
          promedio: 0.92,
          resultado: 'Campeón',
          destacado: true
        },
        { 
          temporada: '2014-2015', 
          equipo: 'Barcelona', 
