                          {bestSeason.resultado === 'Campeón' ? ` Además, logró coronarse campeón de Europa al final de esta temporada.` : ''}
                        </p>
                      </div>
                    </div>
                  </div>

                  <div>
                    <div className="bg-white p-4 rounded-lg shadow-sm border border-gray-200 h-full flex flex-col justify-center items-center">
                      <div className="text-champions-gold text-5xl mb-2">⚽</div>
                      <div className="text-3xl font-bold text-champions-blue">{bestSeason.goles}</div>
                      <div className="text-sm text-gray-500 text-center">Máximo de goles en una<br />temporada</div>
                    </div>
                  </div>
                </div>
              </div>
            )}

            {/* Información de todas las temporadas */}
            <div className="p-6">
              <h3 className="text-xl font-bold text-champions-blue mb-6">Historial de Temporadas</h3>

              {sortedSeasons && sortedSeasons.length > 0 ? (
                <div className="overflow-x-auto">
                  <table className="min-w-full divide-y divide-gray-200">
                    <thead className="bg-gray-50">
                      <tr>
                        <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-champions-blue uppercase tracking-wider">
                          Temporada
                        </th>
                        <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-champions-blue uppercase tracking-wider">
                          Equipo
                        </th>
                        <th scope="col" className="px-6 py-3 text-center text-xs font-medium text-champions-blue uppercase tracking-wider">
                          Goles
                        </th>
                        <th scope="col" className="px-6 py-3 text-center text-xs font-medium text-champions-blue uppercase tracking-wider">
                          Partidos
                        </th>
                        <th scope="col" className="px-6 py-3 text-center text-xs font-medium text-champions-blue uppercase tracking-wider">
                          Promedio
                        </th>
                        <th scope="col" className="px-6 py-3 text-center text-xs font-medium text-champions-blue uppercase tracking-wider">
                          Resultado
                        </th>
