                          <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-champions-blue">
                            {season.temporada}
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-700">
                            {season.equipo}
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-center font-bold text-champions-blue">
                            {season.goles}
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-center text-gray-700">
                            {season.partidos}
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-center text-gray-700">
                            {season.promedio}
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-center">
