                                : season.resultado === 'Finalista'
                                ? 'bg-blue-100 text-blue-800'
                                : 'bg-gray-100 text-gray-800'
                            }`}>
                              {season.resultado}
                            </span>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              ) : (
                <div className="text-center p-8 text-gray-500">
                  No hay información disponible sobre las temporadas de este jugador.
                </div>
              )}

              {/* Resumen de rendimiento */}
              {sortedSeasons && sortedSeasons.length > 0 && (
                <div className="mt-8 p-4 bg-gray-50 rounded-lg border border-gray-200">
                  <h4 className="font-semibold text-champions-blue mb-3">Resumen de Rendimiento</h4>
                  <p className="text-sm text-gray-700">
                    A lo largo de su carrera en la Champions League, {playerData.name} ha participado en {sortedSeasons.length} temporadas, 
                    anotando un total de {detailPlayer.goals} goles.
                    {bestSeason ? ` Su mejor rendimiento fue en la temporada ${bestSeason.temporada} con ${bestSeason.goles} goles en ${bestSeason.partidos} partidos.` : ''}
                    {sortedSeasons.filter(s => s.resultado === 'Campeón').length > 0 ? 
                      ` Ha conseguido ${sortedSeasons.filter(s => s.resultado === 'Campeón').length} título${sortedSeasons.filter(s => s.resultado === 'Campeón').length > 1 ? 's' : ''} de Champions League.` : 
                      ''}
                  </p>
                </div>
              )}
            </div>
          </div>
        </div>
      </main>
    );
  };

  return (
    <div className="min-h-screen flex flex-col">
      <ChampionsLeagueHeader 
        activeView={activeView}
        onNavigate={() => setActiveView('home')}
      />

      {/* Renderizar la vista activa */}
      {activeView === 'home' && renderHomeView()}
      {activeView === 'player-detail' && renderPlayerDetailView()}
      {activeView === 'player-teams' && renderPlayerTeamsView()}
      {activeView === 'player-seasons' && renderPlayerSeasonsView()}

      <ChampionsLeagueFooter />
    </div>
  );
};

export default ChampionsLeagueScorers;
